    active      BOOLEAN NOT NULL DEFAULT true,
    position    INTEGER NOT NULL DEFAULT 0,
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_commerce_offers_product ON commerce.commerce_offers (product_id, position);
CREATE INDEX IF NOT EXISTS idx_commerce_offers_org ON commerce.commerce_offers (org_id);
ALTER TABLE commerce.commerce_offers ENABLE ROW LEVEL SECURITY;
