-- Privacy requests (LGPD art. 18) -- verified by an e-mailed link before anyone acts on them.
CREATE TABLE IF NOT EXISTS commerce.commerce_privacy_requests (
    id           UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    org_id       UUID NOT NULL,
    customer_id  UUID NOT NULL REFERENCES commerce.commerce_customers(id) ON DELETE CASCADE,
    kind         TEXT NOT NULL CHECK (kind IN ('access', 'correction', 'deletion', 'portability', 'revoke_consent')),
    status       TEXT NOT NULL DEFAULT 'open' CHECK (status IN ('open', 'verified', 'done', 'rejected')),
    details      TEXT,
    verified_at  TIMESTAMPTZ,
    created_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
    resolved_at  TIMESTAMPTZ
);
CREATE INDEX IF NOT EXISTS idx_commerce_privacy_requests_customer ON commerce.commerce_privacy_requests (customer_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_commerce_privacy_requests_org ON commerce.commerce_privacy_requests (org_id, status);
ALTER TABLE commerce.commerce_privacy_requests ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "commerce_privacy_requests_select_own_org" ON commerce.commerce_privacy_requests;
CREATE POLICY "commerce_privacy_requests_select_own_org" ON commerce.commerce_privacy_requests FOR SELECT TO authenticated
  USING (org_id = (SELECT public.current_org_id()));
DROP POLICY IF EXISTS "service_role_bypass" ON commerce.commerce_privacy_requests;
CREATE POLICY "service_role_bypass" ON commerce.commerce_privacy_requests FOR ALL TO service_role USING (true) WITH CHECK (true);

-- Orders. token = the opaque public handle; platform_fee_cents is the EXPECTED noc fee (D27). buyer_doc/buyer_name/fiscal_retain_until = the D30 tax-record snapshot taken at `paid` (LGPD art. 16 II + CTN art. 173).
CREATE TABLE IF NOT EXISTS commerce.commerce_orders (
    id                 UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    org_id             UUID NOT NULL,
    token              TEXT NOT NULL UNIQUE,
    customer_id        UUID NOT NULL REFERENCES commerce.commerce_customers(id),
    status             TEXT NOT NULL DEFAULT 'created' CHECK (status IN ('created', 'pending_payment', 'paid', 'expired', 'failed', 'cancelled', 'refunded', 'chargeback')),
    subtotal_cents     INTEGER NOT NULL CHECK (subtotal_cents >= 0),
    discount_cents     INTEGER NOT NULL DEFAULT 0 CHECK (discount_cents >= 0),
    total_cents        INTEGER NOT NULL CHECK (total_cents >= 0),
    currency           TEXT NOT NULL DEFAULT 'BRL',
    coupon_id          UUID REFERENCES commerce.commerce_coupons(id) ON DELETE SET NULL,
    payment_method     TEXT NOT NULL CHECK (payment_method IN ('pix', 'boleto', 'credit_card')),
    gateway            TEXT NOT NULL,
    gateway_charge_id  TEXT,
    checkout_url       TEXT,
    pix_qr             JSONB,
    expires_at         TIMESTAMPTZ,
    paid_at            TIMESTAMPTZ,
    platform_fee_cents INTEGER NOT NULL DEFAULT 0 CHECK (platform_fee_cents >= 0),
    buyer_doc          TEXT,
    buyer_name         TEXT,
    fiscal_retain_until DATE,
    created_at         TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at         TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_commerce_orders_fiscal_retain ON commerce.commerce_orders (fiscal_retain_until)
    WHERE fiscal_retain_until IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_commerce_orders_org_created ON commerce.commerce_orders (org_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_commerce_orders_org_status ON commerce.commerce_orders (org_id, status);
CREATE INDEX IF NOT EXISTS idx_commerce_orders_customer ON commerce.commerce_orders (customer_id);
CREATE INDEX IF NOT EXISTS idx_commerce_orders_charge ON commerce.commerce_orders (gateway_charge_id)
    WHERE gateway_charge_id IS NOT NULL;
ALTER TABLE commerce.commerce_orders ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "commerce_orders_select_own_org" ON commerce.commerce_orders;
CREATE POLICY "commerce_orders_select_own_org" ON commerce.commerce_orders FOR SELECT TO authenticated
  USING (org_id = (SELECT public.current_org_id()));
DROP POLICY IF EXISTS "service_role_bypass" ON commerce.commerce_orders;
CREATE POLICY "service_role_bypass" ON commerce.commerce_orders FOR ALL TO service_role USING (true) WITH CHECK (true);

-- Order items: a SNAPSHOT of what was sold (history survives a product/offer deletion).
CREATE TABLE IF NOT EXISTS commerce.commerce_order_items (
    id               UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    org_id           UUID NOT NULL,
    order_id         UUID NOT NULL REFERENCES commerce.commerce_orders(id) ON DELETE CASCADE,
