    product_type     TEXT NOT NULL CHECK (product_type IN ('digital', 'physical', 'service', 'print_on_demand')),
    fulfillment_type TEXT NOT NULL CHECK (fulfillment_type IN ('digital_delivery', 'shipping', 'pickup', 'local_delivery', 'none')),
    unit_price_cents INTEGER NOT NULL CHECK (unit_price_cents > 0),
    qty              INTEGER NOT NULL CHECK (qty > 0),
    total_cents      INTEGER NOT NULL CHECK (total_cents > 0)
);
CREATE INDEX IF NOT EXISTS idx_commerce_order_items_order ON commerce.commerce_order_items (order_id);
CREATE INDEX IF NOT EXISTS idx_commerce_order_items_org ON commerce.commerce_order_items (org_id);
ALTER TABLE commerce.commerce_order_items ENABLE ROW LEVEL SECURITY;
