DROP POLICY IF EXISTS "service_role_bypass" ON commerce.commerce_order_items;
CREATE POLICY "service_role_bypass" ON commerce.commerce_order_items FOR ALL TO service_role USING (true) WITH CHECK (true);

-- Order events (append-only): every applied transition leaves a row.
CREATE TABLE IF NOT EXISTS commerce.commerce_order_events (
    id           UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    org_id       UUID NOT NULL,
    order_id     UUID NOT NULL REFERENCES commerce.commerce_orders(id) ON DELETE CASCADE,
    from_status  TEXT CHECK (from_status IS NULL OR from_status IN ('created', 'pending_payment', 'paid', 'expired', 'failed', 'cancelled', 'refunded', 'chargeback')),
    to_status    TEXT NOT NULL CHECK (to_status IN ('created', 'pending_payment', 'paid', 'expired', 'failed', 'cancelled', 'refunded', 'chargeback')),
    reason       TEXT,
    source       TEXT NOT NULL CHECK (source IN ('checkout', 'webhook', 'staff', 'system')),
    at           TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_commerce_order_events_order ON commerce.commerce_order_events (order_id, at);
CREATE INDEX IF NOT EXISTS idx_commerce_order_events_org ON commerce.commerce_order_events (org_id);
ALTER TABLE commerce.commerce_order_events ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "commerce_order_events_select_own_org" ON commerce.commerce_order_events;
CREATE POLICY "commerce_order_events_select_own_org" ON commerce.commerce_order_events FOR SELECT TO authenticated
  USING (org_id = (SELECT public.current_org_id()));
DROP POLICY IF EXISTS "service_role_bypass" ON commerce.commerce_order_events;
CREATE POLICY "service_role_bypass" ON commerce.commerce_order_events FOR ALL TO service_role USING (true) WITH CHECK (true);

-- Per-org payment-gateway credentials (Fernet-encrypted; Asaas key + webhook token).
